import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.DXa1R37q.js";const h=JSON.parse('{"title":"Search, concurrency, and recovery","description":"","frontmatter":{},"headers":[],"relativePath":"issues/operations.md","filePath":"issues/operations.md","lastUpdated":1793132902000}'),s={name:"issues/operations.md"};function i(n,e,c,d,l,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="search-concurrency-and-recovery" tabindex="-1">Search, concurrency, and recovery <a class="header-anchor" href="#search-concurrency-and-recovery" aria-label="Permalink to &quot;Search, concurrency, and recovery&quot;">​</a></h1><p><code>issue_search</code> uses a domain-owned SQLite FTS5 index and BM25 ranking across title, body, comments, and scalar metadata. Exact status/type/assignee/parent/location filters are applied. The raw query is byte-bounded before whitespace normalization. The effective row and output-byte budgets are the smaller of the call/retrieval values and the configured security ceilings. Direct-library budgets must be positive safe integers and fail before SQLite is opened. Candidate IDs and revisions are always hydrated from canonical YAML; cache content never becomes returned authority.</p><p>The disposable cache also contains lossless, bounded projections of exact revisions, metadata, persisted hierarchy and relationship edges, comments, and typed links. Health checks compare every structured row and count to the complete YAML snapshot in cancellable, aggregate-bounded keyset pages. Missing, corrupt, wrong-version, stale-digest, failed-integrity, max-age, or contradictory caches either rebuild atomically or return a stable <code>ISSUE_CACHE_STALE</code>/<code>ISSUE_CACHE_REBUILD_REQUIRED</code> error under <code>stale_policy: fail</code>.</p><p>All writes hold the repository authority lease, validate a complete proposed graph, and publish through a durable exact-revision batch. Recursive archive/restore moves the complete subtree. On the next lease acquisition repository-store recovers interrupted journals without overwriting operator changes. Resolve conflicts by inspecting Git and canonical YAML, then retry with the latest returned revision. Symlinks, hard links, special files, unsafe paths, portable path collisions, and configured resource-limit violations fail closed.</p>',4)])])}const y=a(s,[["render",i]]);export{h as __pageData,y as default};
